import React from 'react';
import { CommonProps } from '../utility/commonProps';
export type TextFieldInputType = 'email' | 'number' | 'password' | 'search' | 'tel' | 'text' | 'time' | 'url';
export type TextFieldSize = 'large' | 'medium' | 'small';
export interface ITextFieldProps extends Omit<React.ComponentPropsWithoutRef<'div'>, 'className' | 'onChange' | 'style'>, CommonProps {
    /**
     * If the text field is disabled.
     *
     * @default false
     */
    disabled?: boolean;
    /**
     * The error for the text field.
     */
    error?: React.ReactNode;
    /**
     * The helper text for the text field.
     */
    helperText?: React.ReactNode;
    /**
     * The id for the text field.
     */
    id?: string;
    /**
     * The label for the text field.
     */
    label: React.ReactNode;
    /**
     * The leading icon for the text field.
     */
    leadingIcon?: React.ReactNode;
    /**
     * The callback fired when the text field requests to change.
     */
    onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
    /**
     * The placeholder for the text field.
     */
    placeholder?: string;
    /**
     * If the text field is read only.
     *
     * @default false
     */
    readOnly?: boolean;
    /**
     * The size for the text field.
     *
     * @default "large"
     */
    size?: TextFieldSize;
    /**
     * The props spread to the text field's input element.
     *
     * @default {}
     */
    textFieldProps?: React.ComponentPropsWithoutRef<'input'>;
    /**
     * The trailing content for the text field.
     */
    trailing?: React.ReactNode;
    /**
     * The type for the text field.
     *
     * @default "text"
     */
    type?: TextFieldInputType;
    /**
     * The value for the text field.
     *
     * @default ""
     */
    value?: string;
    /**
     * Boolean prop to enable rounded borders.
     *
     *  @default false
     */
    rounded?: boolean;
}
/**
 * Text Fields allow users to enter and edit text.
 *
 * {@link https://livingdesign.walmart.com/components/text-field/ Guidelines}
 * {@link https://livingdesign.walmart.com/components/text-field/react/ React documentation}
 *
 * ### Content
 *
 * #### Label
 *
 * Text Field requires a label to be accessible. Use the `label` property to add a label:
 *
 * ```tsx
 * <TextField
 *   label="Full name"
 *   onChange={(event) => console.log(event)}
 * />
 * ```
 *
 * #### Helper and error text
 *
 * Set the `helperText` prop to include descriptive helper text below the label:
 *
 * ```tsx
 * <TextField
 *   helperText="Please include middle initials"
 *   label="Full name"
 *   onChange={(event) => console.log(event)}
 * />
 * ```
 *
 * Set the `error` prop to indicate to a user that the Text Field is in a bad state.
 *
 * (Note: `error` overrides `helperText`.)
 *
 * ```tsx
 * <TextField
 *   error="This is wrong."
 *   label="Full name"
 *   onChange={(event) => console.log(event)}
 * />
 * ```
 *
 * #### Leading and trailing
 *
 * Clarify the Text Field's purpose by adding an icon with the `leadingIcon` prop:
 *
 * ```tsx
 * import * as React from "react";
 * import * as Icon from "@livingdesign/icons";
 * import { TextField } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   return (
 *     <TextField
 *       label="Full name"
 *       leadingIcon={<Icon.User />}
 *       onChange={(event) => console.log(event)}
 *     />
 *   );
 * };
 * ```
 *
 * Enhance Text Field's functionality by passing additional content to the `trailing` slot:
 *
 * ```tsx
 * import * as React from "react";
 * import * as Icon from "@livingdesign/icons";
 * import { IconButton, TextField } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   return (
 *     <TextField
 *       label="Full name"
 *       onChange={(event) => console.log(event)}
 *       trailing={
 *         <IconButton a11yLabel="Clear full name">
 *           <Icon.CloseCircleFill />
 *         </IconButton>
 *       }
 *     />
 *   );
 * };
 * ```
 *
 * ### Features
 *
 * #### Size
 *
 * The Text Area comes in two sizes:
 *
 * - `small`
 * - `large` (default)
 *
 * Set the Text Field's size with the `size` property.
 *
 * ```tsx
 * <TextField label="Small" size="small" />
 * <TextField label="Large" size="large" />
 * ```
 *
 * #### Rounded Borders
 *
 * The Text Field comes with rounded borders. Set the value of rounded prop to true to get the rounded borders.
 *
 * ```tsx
 * <TextField label="Rounded Borders" rounded={true} />
 * <Textfield label="Normal Borders" rounded={false} /> (default)
 * ````
 *
 * ### Interaction
 *
 * Configure the Text Field's value using the `value` property. Respond to changes by passing an callback handler to the `onChange` prop:
 *
 * ```tsx
 * import * as React from "react";
 * import { TextField } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   const [value, setValue] = React.useState("CA");
 *
 *   return (
 *     <TextField
 *       label="Full name"
 *       onChange={(event) => setValue(event.target.value)}
 *       value={value}
 *     />
 *   );
 * };
 * ```
 */
export declare const TextField: React.ForwardRefExoticComponent<ITextFieldProps & React.RefAttributes<HTMLInputElement>>;
